-- IPA 2020-07-26: individually checked adaptations and answer key.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20200726-q03','exam-fe','経路の数','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問3・改編】格子上でPから右に2区画・上に2区画進んだ点をR、さらにRから右に3区画・上に2区画進んだ点をQとする。PからRを通りQまで最短経路で進む方法は何通りか。','[{"id":"a","text":"16"},{"id":"b","text":"24"},{"id":"c","text":"32"},{"id":"d","text":"60"}]','"d"','P→Rは4歩から右2歩を選ぶ6通り、R→Qは5歩から上2歩を選ぶ10通り。積は60。中文：两段最短路分别为C(4,2)=6和C(5,2)=10，总数为60。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q04','exam-fe','二分法','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問4・改編】連続単調増加関数fについてf(0)<0≦f(1)とする。区間[0,1]の中点を計算し、右端と中点の差が0.001未満なら終了、それ以外は符号に応じて区間を半分にする。中点計算は何回行うか。','[{"id":"a","text":"10"},{"id":"b","text":"20"},{"id":"c","text":"100"},{"id":"d","text":"1000"}]','"a"','n回目の右端と中点の差は2の−n乗。2⁻⁹＝0.001953…、2⁻¹⁰＝0.000976…なので10回。中文：每次减半，第10次才小于0.001。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q05','exam-fe','後置記法','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問5・改編】Y＝(A＋B)×(C−D÷E)を後置記法で表したものはどれか。代入は最後に「＝」を置く。','[{"id":"a","text":"YAB＋C−DE÷×＝"},{"id":"b","text":"YAB＋CDE÷−×＝"},{"id":"c","text":"YAB＋EDC÷−×＝"},{"id":"d","text":"YBA＋CD−E÷×＝"}]','"b"','A B ＋、C D E ÷ −をそれぞれ作り、×、最後に代入する。中文：先将括号内转成后缀表达式，再依次放乘号和赋值号。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q06','exam-fe','フィードバック制御','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問6・改編】黒い線に沿って走る車に左右の光センサと独立した左右の車輪がある。センサは黒い部分に多くかかるほど出力が小さい。左右の出力が異なるとき、線に戻るための速度制御はどれか。','[{"id":"a","text":"左出力＞右出力でも左出力＜右出力でも、左輪を上げ右輪を下げる"},{"id":"b","text":"左出力＞右出力なら左輪を上げ右輪を下げ、逆なら左輪を下げ右輪を上げる"},{"id":"c","text":"左出力＞右出力なら左輪を下げ右輪を上げ、逆なら左輪を上げ右輪を下げる"},{"id":"d","text":"左出力＞右出力でも左出力＜右出力でも、左輪を下げ右輪を上げる"}]','"b"','左出力が大きいと右側がより黒いので右へ曲がるため左輪を速くする。逆なら左へ曲がる。中文：输出较小的一侧更靠近黑线，须朝该侧转向。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q07','exam-fe','二分木の後順巡回','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問7・改編】根が「＋」、左の子がa、右の子が「＊」で、＊の左の子は「−」（その子は左b・右c）、右の子はdである。左右の部分木を順に訪問し最後に自ノードを出力すると、結果はどれか。','[{"id":"a","text":"＋a＊−bcd"},{"id":"b","text":"a＋b−c＊d"},{"id":"c","text":"abc−d＊＋"},{"id":"d","text":"b−c＊d＋a"}]','"c"','後順では左部分木、右部分木、根の順。右部分木はbc−d＊となる。中文：后序遍历按左、右、根输出，结果为abc−d＊＋。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q08','exam-fe','スタック','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問8・改編】加減乗除の式を処理する際、スタックに適した用途はどれか。','[{"id":"a","text":"保存順に途中結果を取り出す"},{"id":"b","text":"途中結果を保存して別の計算後、その結果と保存した途中結果を計算する"},{"id":"c","text":"昇順に並べた途中結果の中央だけ変更する"},{"id":"d","text":"リストの中央へ途中結果を挿入する"}]','"b"','括弧などで中断した計算の途中結果を積み、後で最後に積んだ値から取り出せる。中文：栈后进先出，适合暂存嵌套计算的中间结果。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q09','exam-fe','配列操作','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問9・改編】配列TANGOの1〜nに単語がある。n番目を1番目へ移し、元の1〜n−1番目を一つずつ後ろへずらす。最初にTANGO[0]←TANGO[n]とし、iをn−1から0まで減らすループの処理はどれか。','[{"id":"a","text":"TANGO[i]←TANGO[n−i]"},{"id":"b","text":"TANGO[i＋1]←TANGO[i]"},{"id":"c","text":"TANGO[n−i]←TANGO[i]"},{"id":"d","text":"TANGO[n−i]←TANGO[i＋1]"}]','"b"','後ろから右隣へコピーする。最後のi＝0で退避した単語が1番目に入る。中文：从尾部向右移动，最后将0号暂存值放到1号。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q10','exam-fe','XML','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問10・改編】XMLに関する説明として適切なものはどれか。','[{"id":"a","text":"HTMLを基に機能を拡張したものである"},{"id":"b","text":"XML文書の入力には専用エディタが必要である"},{"id":"c","text":"タグを定義して文書の属性情報や論理構造を表せる"},{"id":"d","text":"文書の論理構造と表示スタイルを一体化したものである"}]','"c"','XMLは用途に応じたタグでデータの構造を表現できる。中文：XML可定义标签来表达数据结构；不要求专用编辑器。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q11','exam-fe','パイプライン','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問11・改編】各命令が5段のパイプラインを通り、各段は1サイクルで完了する。停止や競合がない場合、20命令の完了に必要なサイクル数はどれか。','[{"id":"a","text":"20"},{"id":"b","text":"21"},{"id":"c","text":"24"},{"id":"d","text":"25"}]','"c"','最初の命令に5サイクル、残り19命令は1サイクルずつ完了するので24サイクル。中文：首条耗时5周期，后续19条每周期完成一条，共24周期。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q14','exam-fe','磁気ディスク','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問14・改編】磁気ディスクの性能に関する適切な説明はどれか。','[{"id":"a","text":"回転速度を上げるか位置決め時間を短縮するとアクセス時間は短くなる"},{"id":"b","text":"アクセス時間には処理装置の前処理時間と転送後の後処理時間も含む"},{"id":"c","text":"記憶容量はトラック当たりの容量と1シリンダ当たりのトラック数だけで決まる"},{"id":"d","text":"データ転送速度は回転速度と回転待ち時間だけで決まる"}]','"a"','アクセス時間は位置決め時間、回転待ち時間、転送時間などからなる。中文：提高转速可缩短旋转等待，缩短寻道也能减少访问时间。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q15','exam-fe','フォールトトレランス','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問15・改編】一部の構成要素が故障しても処理を継続できるシステムの実現に不可欠な考え方はどれか。','[{"id":"a","text":"構成に冗長性を持たせ故障の影響を局所化する"},{"id":"b","text":"障害原因の調査に備えてデータベース変更履歴を記録する"},{"id":"c","text":"障害後に予備環境へ復旧できるよう定期バックアップする"},{"id":"d","text":"操作ミスが重大な誤りにならないよう設計する"}]','"a"','フォールトトレランスは障害発生時も機能を継続するため、冗長化などを使う。中文：容错需要在部分故障时维持运行，可通过冗余实现。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q16','exam-fe','稼働率','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問16・改編】CPU1台、磁気ディスク2台、サイト2か所の構成がある。各サイトには端末が2台あり、CPUと2台のディスク全て、および各サイトで少なくとも1台の端末が正常ならシステムは稼働する。各装置は独立し、1台の稼働率はCPUがC、ディスクがD、端末がTである。全体の稼働率はどれか。','[{"id":"a","text":"D²C(1−T²)²"},{"id":"b","text":"D²C{1−(1−T)²}²"},{"id":"c","text":"(1−D)²C(1−T²)²"},{"id":"d","text":"(1−D)²C{1−(1−T)²}²"}]','"b"','2ディスクとCPUは直列、各サイトの2端末は並列。各サイトの稼働率は1−(1−T)²。中文：磁盘和CPU均须工作，各站点只需两个终端中至少一个工作。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q17','exam-fe','スプーリング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問17・改編】スプーリングの説明として適切なものはどれか。','[{"id":"a","text":"キーボードの入力を主記憶のキューに一時保存する"},{"id":"b","text":"ジョブの特性や優先順位に応じて実行順序を決める"},{"id":"c","text":"通信データを登録済みの代理に送る"},{"id":"d","text":"低速なプリンタなどへの出力を一旦磁気ディスクに保存し後で出力する"}]','"d"','低速装置への出力を補助記憶に一時保存し、装置の処理とプログラム実行を分離する。中文：假脱机先将输出写入磁盘，再交由低速设备处理。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q18','exam-fe','コンパイラ最適化','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問18・改編】コンパイラの最適化の主な目的はどれか。','[{"id":"a","text":"プログラムの実行時間を短縮する"},{"id":"b","text":"プログラムのデバッグを容易にする"},{"id":"c","text":"プログラムの保守性を改善する"},{"id":"d","text":"目的プログラムを生成する時間を短縮する"}]','"a"','意味を変えずに生成コードを改善して実行効率を高める。中文：编译器优化在保持语义的前提下提升生成代码的执行效率。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q19','exam-fe','オープンソース','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問19・改編】OSIのオープンソース定義に基づくOSSの特徴として適切なものはどれか。','[{"id":"a","text":"無償で入手できるが商用システムでの利用は禁止される"},{"id":"b","text":"OSSをパッケージ化し自社ソフトと組み合わせて有償販売できる"},{"id":"c","text":"利用者が一定数を超えると必ずライセンス料が発生する"},{"id":"d","text":"改良は自由だが改良版を再配布できない"}]','"b"','オープンソースは商用利用や販売を一律に禁じない。ただし個々のライセンス条件は守る。中文：开源软件可以商业使用和销售，仍须遵守对应许可证。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q21','exam-fe','音声データ量','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問21・改編】音声を10kHz、量子化16ビットで4秒間サンプリングし、データ量を1/4に圧縮した。1kバイト＝1000バイトとして圧縮後の量は何kバイトか。','[{"id":"a","text":"10"},{"id":"b","text":"20"},{"id":"c","text":"80"},{"id":"d","text":"160"}]','"b"','10000×16×4ビット÷8÷4＝20000バイト。中文：每秒10000次、每次2字节，4秒共80kB，压缩后20kB。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q22','exam-fe','論理回路','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問22・改編】X＝(¬A∧B)∨(A∧¬B)∨(¬A∧¬B)と等価な論理回路はどれか。','[{"id":"a","text":"AND"},{"id":"b","text":"NAND"},{"id":"c","text":"OR"},{"id":"d","text":"NOR"}]','"b"','Xが0になるのはAもBも1のときだけなのでNAND。中文：只有A和B均为1时输出0，等价于与非门。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q23','exam-fe','チェックディジット','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問23・改編】データ7394と重み1234の各桁を掛けた合計を11で割り、11から余りを引いた数の1の位を末尾に付ける。結果はどれか。','[{"id":"a","text":"73940"},{"id":"b","text":"73941"},{"id":"c","text":"73944"},{"id":"d","text":"73947"}]','"a"','7×1＋3×2＋9×3＋4×4＝56、56÷11の余りは1。11−1＝10の1の位は0。中文：加权和56，除11余1，校验位是10的个位0。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q25','exam-fe','ストアドプロシージャ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問25・改編】クライアント・サーバ間の通信負荷を減らすため、よく使う命令群をサーバ側のDBMSにあらかじめ格納する仕組みはどれか。','[{"id":"a","text":"2相コミットメント"},{"id":"b","text":"グループコミットメント"},{"id":"c","text":"サーバプロセスのマルチスレッド化"},{"id":"d","text":"ストアドプロシージャ"}]','"d"','DBMS側の手続きを呼び出すことで命令を逐次送る回数を減らせる。中文：存储过程把常用处理保存在数据库服务器端，减少网络往返。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q26','exam-fe','関係モデル','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問26・改編】関係モデルとその実装である関係データベースの対応について適切なものはどれか。','[{"id":"a","text":"関係は表に対応付けられる"},{"id":"b","text":"属性も列も左から右に順序付けられる"},{"id":"c","text":"タプルも行も必ず重複しない"},{"id":"d","text":"定義域は文字型または文字列型に対応する"}]','"a"','関係は表、属性は列、タプルは行に対応する。SQLの表には重複行もあり得る。中文：关系对应表；SQL表可能包含重复行，定义域也不局限于字符类型。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q27','exam-fe','関数従属性','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問27・改編】属性間にa→b,c,d,e、b→f,g,h、e→i,jという関数従属性がある。推移的従属を分離し3表にする組合せはどれか。','[{"id":"a","text":"(a)、(b,c,d,e)、(f,g,h,i,j)"},{"id":"b","text":"(a,b,c,d,e)、(b,f,g,h)、(e,i,j)"},{"id":"c","text":"(a,b,f,g,h)、(c,d)、(e,i,j)"},{"id":"d","text":"(a,c,d)、(b,f,g,h)、(e,i,j)"}]','"b"','aに直接従属する属性と、bおよびeに従属する属性をそれぞれ分け、bとeを連結に残す。中文：分离传递依赖，同时保留连接所需的b和e。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q29','exam-fe','参照整合性','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問29・改編】注文表の顧客番号は顧客表の主キーを参照する外部キーである。顧客はC005、D010、K001、L035で、注文はC005、K001、C005、D010を参照する。参照整合性を損なう操作はどれか。','[{"id":"a","text":"参照されていないL035の顧客行を削除する"},{"id":"b","text":"顧客番号D010の注文を追加する"},{"id":"c","text":"顧客番号F020の注文を追加する"},{"id":"d","text":"顧客番号K001の注文を削除する"}]','"c"','F020は顧客表に存在せず、外部キーの参照先がなくなる。中文：F020不在客户表，新增该订单会违反外键参照完整性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q30','exam-fe','LAN接続装置','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問30・改編】複数のLANを接続し、OSI参照モデルのデータリンク層の情報に基づいて中継する装置はどれか。','[{"id":"a","text":"ゲートウェイ"},{"id":"b","text":"ブリッジ"},{"id":"c","text":"リピータ"},{"id":"d","text":"ルータ"}]','"b"','ブリッジはデータリンク層でMACアドレスなどに基づきフレームを中継する。中文：网桥工作在数据链路层；路由器主要工作在网络层。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q31','exam-fe','DHCP','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問31・改編】LANに接続されたPCに起動時などにIPアドレスを自動設定するためのプロトコルはどれか。','[{"id":"a","text":"DHCP"},{"id":"b","text":"DNS"},{"id":"c","text":"FTP"},{"id":"d","text":"PPP"}]','"a"','DHCPはIPアドレスなどのネットワーク設定を自動配布する。中文：DHCP自动分配IP地址等配置，DNS主要负责名称解析。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q35','exam-fe','SQLインジェクション','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問35・改編】SQLインジェクションの説明として適切なものはどれか。','[{"id":"a","text":"SQL呼出しの不備を悪用した文字列入力でデータを不正取得・改ざん・削除する"},{"id":"b","text":"大量パケットでトラフィックを増やしサービスを停止させる"},{"id":"c","text":"メモリ領域の範囲外に書き込み不正コードを実行する"},{"id":"d","text":"罠のリンクを通じて不正スクリプトをレスポンスに埋め込み実行させる"}]','"a"','入力の扱いが不適切なSQLを細工してデータベースを不正操作する。中文：SQL注入利用输入拼接SQL的缺陷操作数据库。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q37','exam-fe','パスワードの組合せ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問37・改編】使用できる文字がM種類、パスワードの長さがn文字である。各位置で文字を重複して選べるとき、理論上のパスワード総数はどれか。','[{"id":"a","text":"Mⁿ"},{"id":"b","text":"M!／(M−n)!"},{"id":"c","text":"M!／{n!(M−n)!}"},{"id":"d","text":"(M＋n−1)!／{n!(M−1)!}"}]','"a"','各桁にM通りの選択肢が独立にあるのでMをn回掛ける。中文：每一位均有M种选择且允许重复，总数为M的n次方。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q40','exam-fe','WAF','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問40・改編】クライアントからWebサーバへ送信されるデータを検査し、SQLインジェクションなどの攻撃を遮断するものはどれか。','[{"id":"a","text":"SSL-VPN機能"},{"id":"b","text":"WAF"},{"id":"c","text":"クラスタ構成"},{"id":"d","text":"ロードバランシング機能"}]','"b"','WAFはWebアプリケーションへのHTTPリクエストを検査して攻撃を検知・遮断する。中文：Web应用防火墙可检测并阻断恶意Web请求。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q41','exam-fe','アクセス権','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問41・改編】読取り・書込み・実行の各権限を1ビットずつで設定する。0では全て不可、3では読取りと書込みのみ可能、7では全て可能だった。適切な説明はどれか。','[{"id":"a","text":"2を設定すると読取りと実行ができる"},{"id":"b","text":"4を設定すると実行だけができる"},{"id":"c","text":"5を設定すると書込みだけができる"},{"id":"d","text":"6を設定すると読取りと書込みができる"}]','"b"','3は二進数011で読取りと書込みが有効。7は111なので残る100、つまり4が実行権限。中文：3包含读写，7比3多出的位为4，因此4仅表示执行。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q42','exam-fe','通信の暗号化','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問42・改編】クライアントのアプリとサーバのデータベース間で送受信するコマンドや実行結果が通信途中で盗聴されることを防ぐ対策はどれか。','[{"id":"a","text":"接続可能なクライアントのIPアドレスを制限する"},{"id":"b","text":"サーバ側接続プログラムの起動・停止パスワードを設定する"},{"id":"c","text":"接続に使うポート番号を初期値から変更する"},{"id":"d","text":"接続プログラム間の通信を暗号化する"}]','"d"','通信経路の暗号化は盗聴者が内容を読み取ることを防ぐ。中文：加密传输可防止窃听者读取命令与结果。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q44','exam-fe','ブロックチェーン','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問44・改編】取引履歴とハッシュ値を連結した分散台帳を多数のコンピュータで同期・管理し、改ざんを検出しやすくする技術はどれか。','[{"id":"a","text":"MAC"},{"id":"b","text":"XML署名"},{"id":"c","text":"ニューラルネットワーク"},{"id":"d","text":"ブロックチェーン"}]','"d"','ブロックチェーンはハッシュでブロックをつなぎ、分散した台帳で履歴を管理する。中文：区块链通过哈希连接区块，并由多节点维护账本。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q45','exam-fe','UML汎化','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問45・改編】UMLクラス図で汎化の関係を示すものはどれか。','[{"id":"a","text":"自動車と車検証を1対1の関連で結ぶ"},{"id":"b","text":"スポーツカーから自動車へ実線と白抜き三角形の矢印を向ける"},{"id":"c","text":"自動車からタイヤとエンジンへ黒いひし形の合成関係で結ぶ"},{"id":"d","text":"ドライバから自動車へ破線矢印を向ける"}]','"b"','汎化は下位クラスから上位クラスへ実線と白抜き三角形で表す。中文：泛化用从子类指向父类的空心三角实线表示。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q46','exam-fe','継承','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問46・改編】オブジェクト指向で、あるクラスの属性や機能をサブクラスで利用できることを何というか。','[{"id":"a","text":"オーバーライド"},{"id":"b","text":"カプセル化"},{"id":"c","text":"継承"},{"id":"d","text":"多相性"}]','"c"','継承によりサブクラスは基底クラスの属性や振る舞いを引き継ぐ。中文：继承使子类能够获得父类定义的属性和功能。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q48','exam-fe','スタブ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問48・改編】スタブを使用したテストの説明として適切なものはどれか。','[{"id":"a","text":"指定命令の実行時にレジスタや主記憶の内容を出力する"},{"id":"b","text":"トップダウンテストで仮の下位モジュールを用意して動作を確認する"},{"id":"c","text":"実行中に変数の内容を表示・修正しテストを続行する"},{"id":"d","text":"単体テストで対象を呼び出す仮の上位モジュールを用意する"}]','"b"','スタブはテスト対象から呼ばれる下位モジュールの代役。呼出し元の代役はドライバ。中文：桩模拟被调用的下层模块；驱动程序模拟调用方。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q50','exam-fe','リバースエンジニアリング','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問50・改編】ソフトウェアのリバースエンジニアリングの説明はどれか。','[{"id":"a","text":"設計情報からソースコードを自動生成する"},{"id":"b","text":"外部からの振る舞いを変えずに内部構造を変更する"},{"id":"c","text":"既存ソフトウェアを解析し仕様や構造を明らかにする"},{"id":"d","text":"既存ソフトウェアを理解した上で全体を新しく構築し直す"}]','"c"','既存の成果物を解析して設計や仕様などを把握する。中文：逆向工程从已有软件分析其规格和结构。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q51','exam-fe','ファンクションポイント','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問51・改編】ファンクションポイント法の説明はどれか。','[{"id":"a","text":"プログラムごとのステップ数を積算する"},{"id":"b","text":"WBSの各作業の工数を見積もる"},{"id":"c","text":"外部入出力や内部論理ファイルなどの個数と特性から開発規模を見積もる"},{"id":"d","text":"過去の類似例との相違を分析して開発規模を見積もる"}]','"c"','利用者から見た機能の種類・個数などを基に規模を測る。中文：功能点法根据输入、输出、文件等用户功能的数量与复杂度估算规模。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q54','exam-fe','パレート図','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問54・改編】管理項目別の課題件数を多い順の棒グラフに並べ、累積件数の折れ線を重ねた図はどれか。','[{"id":"a","text":"管理図"},{"id":"b","text":"散布図"},{"id":"c","text":"特性要因図"},{"id":"d","text":"パレート図"}]','"d"','パレート図は項目別の頻度と累積割合を示し重点課題を見つける。中文：帕累托图按数量降序显示柱状图，并叠加累计曲线。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q55','exam-fe','問題管理','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問55・改編】ITサービスマネジメントの問題管理で実施することはどれか。','[{"id":"a","text":"インシデント後に暫定的にサービスを復旧する"},{"id":"b","text":"インシデントの未知の根本原因を特定し恒久的な解決策を策定する"},{"id":"c","text":"インシデントに備え復旧のための設計をする"},{"id":"d","text":"発生を記録し関係部門へ状況を連絡する"}]','"b"','問題管理は根本原因を調査し、再発防止や恒久対策を図る。中文：问题管理调查根因并制定永久解决方案。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q56','exam-fe','バックアップ計画','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問56・改編】新規システムのバックアップ方法について最も適切なものはどれか。','[{"id":"a","text":"業務処理と重なると応答が悪化する場合、重ならないよう予定を組む"},{"id":"b","text":"時間短縮のためバックアップを元データと同じ媒体に置く"},{"id":"c","text":"復旧時間を短くするため常に差分バックアップを採用する"},{"id":"d","text":"長期保存には必ずランダムアクセス可能な媒体を使う"}]','"a"','業務への影響を考えてバックアップ時間を計画する。同一媒体では媒体故障時に両方失う。中文：备份应避免影响业务，并避免与原数据保存在同一故障介质。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q57','exam-fe','SLA可用性','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問57・改編】営業日30日、サービス時間は各日8時から22時まで、計画停止なし。SLAの可用性99.5%以上を満たす月内の最大停止時間は何時間か。','[{"id":"a","text":"0.3"},{"id":"b","text":"2.1"},{"id":"c","text":"3.0"},{"id":"d","text":"3.6"}]','"b"','サービス時間は14×30＝420時間。許容停止は420×0.005＝2.1時間。中文：每月服务420小时，可停机0.5%，即2.1小时。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q59','exam-fe','ソフトウェア資産監査','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問59・改編】ソフトウェア資産管理の監査で確認する事項として最も適切なものはどれか。','[{"id":"a","text":"提供元の開発体制"},{"id":"b","text":"導入時の既存システムとの整合性評価"},{"id":"c","text":"ライセンス証書などの証拠の保管"},{"id":"d","text":"データベース分割による障害の局所化"}]','"c"','ライセンスの保有・使用状況を示す証拠を管理し、利用条件への適合を確認する。中文：审计软件资产时应确认许可证等证明材料得到保存。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q60','exam-fe','バックアップ保管','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問60・改編】災害時の事業継続に備えるバックアップの監査で、指摘すべき状況はどれか。','[{"id":"a","text":"取得手順と担当者を定めている"},{"id":"b","text":"事前の計画に沿って復旧試験を行う"},{"id":"c","text":"秘密保持契約を結んだ外部倉庫で媒体を保管する"},{"id":"d","text":"業務システムが稼働するサーバの近くで媒体を保管する"}]','"d"','サーバとバックアップが同じ災害で同時に失われる恐れがあるため、離れた場所で保管する。中文：备份与服务器放在附近可能同时受灾，应异地保管。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q61','exam-fe','ROI','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問61・改編】情報化投資の評価指標ROIの説明はどれか。','[{"id":"a","text":"売上増やコスト削減で創出された利益額を投資額で割ったもの"},{"id":"b","text":"売上高投資金額比や従業員当たり投資額を他社と比較したもの"},{"id":"c","text":"現金流入の現在価値から現金流出の現在価値を差し引いたもの"},{"id":"d","text":"プロジェクトを実施しない場合の市場での競争力を表すもの"}]','"a"','ROIは投資に対する利益の比率。現金流入と流出の現在価値の差はNPV。中文：投资回报率是收益与投资额之比；现值之差是净现值。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q62','exam-fe','KPI','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問62・改編】物流コスト10%削減を目標に、在庫削減と誤出荷削減に取り組む。「在庫日数7日以内」「誤出荷率3%以内」を設定する活動はどれか。','[{"id":"a","text":"CSFの抽出"},{"id":"b","text":"KGIの設定"},{"id":"c","text":"KPIの設定"},{"id":"d","text":"MBOの導入"}]','"c"','在庫日数や誤出荷率は目標の達成過程を測る業績評価指標。中文：库存天数和误发率是衡量过程表现的KPI。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q63','exam-fe','ビジネスインテリジェンス','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問63・改編】BIの説明として適切なものはどれか。','[{"id":"a","text":"企業内外のデータを蓄積・分析し意思決定を支援する"},{"id":"b","text":"業務プロセスを抜本的に再構築する"},{"id":"c","text":"業務の流れを可視化して継続改善する"},{"id":"d","text":"異なるシステムを連結してデータとプロセスを統合する"}]','"a"','BIはデータを分析し意思決定に活用する。中文：商业智能通过整合与分析数据辅助企业决策。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q64','exam-fe','バランススコアカード','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問64・改編】IT投資の評価指標にバランススコアカードを用いる場合、内部ビジネスプロセスの視点に立つKPIはどれか。','[{"id":"a","text":"売上高営業利益率を前年比5%上げる"},{"id":"b","text":"顧客クレームを月20件以内にする"},{"id":"c","text":"新システム研修の受講率を100%にする"},{"id":"d","text":"注文受付から製品出荷までを3日短縮する"}]','"d"','受注から出荷までの時間は社内業務プロセスの効率を測る。中文：订单到出货的时间属于内部流程指标。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q65','exam-fe','要件定義','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問65・改編】企画、要件定義、システム開発、実装、保守というプロセスのうち、要件定義で行うことはどれか。','[{"id":"a","text":"利害関係者の種類、ニーズ、要望、制約条件を識別する"},{"id":"b","text":"事業目標に必要なシステム化の方針と実施計画を立案する"},{"id":"c","text":"システム機能を定義しハードウェアとソフトウェアの実現方式を確立する"},{"id":"d","text":"ソフトウェアの方式設計と適格性確認を行う"}]','"a"','利害関係者のニーズや制約を把握することは要件定義に含まれる。中文：需求定义需要识别相关方的需求、期望和限制。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q66','exam-fe','SCM','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問66・改編】SCMの目的はどれか。','[{"id":"a","text":"顧客情報や購買履歴を管理し良好な顧客関係を築く"},{"id":"b","text":"商談状況を管理して営業効率を高める"},{"id":"c","text":"生産・販売・会計などの基幹情報を統合する"},{"id":"d","text":"複数企業にまたがる調達から販売までの情報を統合しコスト低減や納期短縮を図る"}]','"d"','SCMは企業間を含む供給網を一体的に管理する。中文：供应链管理贯通采购、生产、物流和销售以提高整体效率。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q68','exam-fe','アンゾフの成長マトリックス','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問68・改編】アンゾフの成長マトリックスにおける多角化戦略はどれか。','[{"id":"a","text":"新製品を現在の市場に投入する"},{"id":"b","text":"技術開発や提携、M&Aなどで新たな製品と市場に成長機会を求める"},{"id":"c","text":"現市場で既存製品の広告を強化する"},{"id":"d","text":"既存製品で海外の新市場を開拓する"}]','"b"','多角化は新製品と新市場の組合せ。中文：多元化战略同时进入新产品和新市场。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q69','exam-fe','クラスタ分析','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問69・改編】観測データを類似性に基づいて集団に分類し、各集団の特徴を調べる手法はどれか。','[{"id":"a","text":"クラスタ分析"},{"id":"b","text":"指数平滑法"},{"id":"c","text":"デルファイ法"},{"id":"d","text":"モンテカルロ法"}]','"a"','クラスタ分析は似たデータをグループ化する。中文：聚类分析按相似性将数据划分为若干组。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q70','exam-fe','段取り時間','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問70・改編】仕事a,b,c,dを各1回行う。次の仕事への段取り時間は、a→b=2,a→c=1,a→d=2、b→a=1,b→c=1,b→d=2、c→a=3,c→b=2,c→d=2、d→a=4,d→b=3,d→c=2時間。順序を自由に決めたとき最小の合計段取り時間は何時間か。','[{"id":"a","text":"4"},{"id":"b","text":"5"},{"id":"c","text":"6"},{"id":"d","text":"7"}]','"a"','b→a→c→dなら1＋1＋2＝4時間。1時間の辺はb→a、a→c、b→cであり3本を連続して使えないため3時間以下にはならない。中文：b→a→c→d为4小时；所有1小时转换无法组成四项工作的完整路径。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q72','exam-fe','RFID','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問72・改編】RFIDの説明はどれか。','[{"id":"a","text":"ICカード等に保存した金銭価値による決済手段"},{"id":"b","text":"集積回路とアンテナを組み合わせ無線で対象を識別する技術"},{"id":"c","text":"白黒の格子模様で数字や文字を格納するもの"},{"id":"d","text":"指紋などの身体的特徴を個人認証に使う技術"}]','"b"','RFIDは電波でタグと情報をやり取りして対象を識別する。中文：RFID通过芯片和天线进行无线识别。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q73','exam-fe','スマートメータ','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問73・改編】通信機能を持つスマートメータを導入する目的として適切でないものはどれか。','[{"id":"a","text":"自動検針で作業効率を高める"},{"id":"b","text":"停電時に補助電源で一定時間電力を供給し続ける"},{"id":"c","text":"電力需要制御でピークを抑える"},{"id":"d","text":"使用量を可視化し節電意識を高める"}]','"b"','スマートメータは計測・通信に使い、停電時に電力供給を継続する装置ではない。中文：智能电表用于计量和通信，本身不负责停电供电。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q75','exam-fe','ABC分析','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問75・改編】ABC分析を適用する事例はどれか。','[{"id":"a","text":"買い物時の購入商品の組合せを把握する"},{"id":"b","text":"商品別の販売金額や粗利益額から売れ筋を把握する"},{"id":"c","text":"品切れ防止のため細かな販売見込数量を把握する"},{"id":"d","text":"地域ごとのオピニオンリーダにアンケートして市場ニーズを把握する"}]','"b"','金額などの大きさで商品を順位付けし、累積比率により重点管理対象を分類する。中文：ABC分析按销售额或利润等指标排序，找出应重点管理的商品。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q77','exam-fe','先入先出法','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問77・改編】4月1日の繰越在庫は2000個×100円、5日の購入は3000個×130円。10日に3000個を払い出すとき、先入先出法による平均払出単価は何円か。','[{"id":"a","text":"100"},{"id":"b","text":"110"},{"id":"c","text":"115"},{"id":"d","text":"118"}]','"b"','古い2000個と新しい1000個を払い出す。合計330000円を3000個で割り110円。中文：先出旧库存2000个，再出新库存1000个，平均单价110日元。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q78','exam-fe','損益分岐点','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問78・改編】損益分岐点の性質として適切なものはどれか。','[{"id":"a","text":"固定費が同じなら変動費率が低くなるほど損益分岐点は高くなる"},{"id":"b","text":"固定費が同じなら変動費率と損益分岐点は正比例する"},{"id":"c","text":"損益分岐点の売上高は固定費と変動費の和に等しい"},{"id":"d","text":"変動費率が同じなら固定費が小さいほど損益分岐点は高くなる"}]','"c"','損益分岐点では利益が0で、売上高＝固定費＋変動費となる。中文：盈亏平衡点的利润为零，销售额等于固定费用与变动费用之和。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q79','exam-fe','出向と派遣','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問79・改編】企業Aに雇用される労働者Cと、企業Bとの関係について適切なものはどれか。','[{"id":"a","text":"Aが請負受託者、Bが委託者ならBとCに指揮命令関係が生じる"},{"id":"b","text":"AがBへCを出向させる場合、BとCに指揮命令関係が生じる"},{"id":"c","text":"Aが派遣元、Bが派遣先ならBとCにも当然に雇用関係が生じる"},{"id":"d","text":"Aが派遣元、Bが派遣先ならCはBに出向している"}]','"b"','出向先で働く場合は出向先の指揮命令を受ける。派遣では通常、派遣元との雇用を維持し派遣先が指揮命令する。中文：出向者在出向目的地接受工作指挥；派遣通常由派遣公司雇用、派遣目的地指挥。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20200726-q80','exam-fe','製造物責任法','standard','single_choice','【IPA 2020年度 修了認定試験 2020-07-26 問80・改編】制御用ソフトウェアがエレベータ制御装置に組み込まれている場合、製造物責任法の対象となる不具合はどれか。','[{"id":"a","text":"可動部品の交換を早める原因となった不具合"},{"id":"b","text":"出荷前に発見された動作不良の原因となる不具合"},{"id":"c","text":"待ち時間が長くなる原因となった不具合"},{"id":"d","text":"人的被害が出たエレベータ事故の原因となった不具合"}]','"d"','製造物の欠陥により人の生命・身体などに損害が生じたケースが対象となる。中文：嵌入设备的缺陷造成人身损害时，可能适用产品责任法。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20200726_FE.pdf','ja','A','explicit','standard','fe_exemption');

